        .callout-warning {{ background: #fef3c7; }}
        .callout-success {{ background: #d1fae5; }}
    </style>
</head>
<body>
    <h1>{self._title}</h1>
    {f'<p><em>{self._subtitle}</em></p>' if self._subtitle else ''}
    <hr>
"""
        # Add basic content (simplified)
        for elem_type, content, meta in self._elements:
            if elem_type == 'text':
                html += f"<p>{content}</p>\n"
            elif elem_type == 'heading':
                level = min(meta if isinstance(meta, int) else 2, 6)
                html += f"<h{level}>{content}</h{level}>\n"
            elif elem_type == 'bullets':
                html += "<ul>\n"
                for item in content:
                    html += f"  <li>{item}</li>\n"
                html += "</ul>\n"
            elif elem_type == 'numbered':
                html += "<ol>\n"
                for item in content:
                    html += f"  <li>{item}</li>\n"
                html += "</ol>\n"
            elif elem_type == 'table':
                import pandas as pd
                if isinstance(content, pd.DataFrame):
                    html += content.to_html(index=False, border=1) + "\n"
                elif isinstance(content, list) and content:
                    if isinstance(content[0], dict):
                        headers = list(content[0].keys())
                        html += "<table><tr>" + "".join(f"<th>{h}</th>" for h in headers) + "</tr>\n"
                        for row in content:
                            html += "<tr>" + "".join(f"<td>{row.get(h, '')}</td>" for h in headers) + "</tr>\n"
                        html += "</table>\n"
            elif elem_type == 'callout':
                style = meta or 'info'
                html += f'<div class="callout callout-{style}"><p>{content}</p></div>\n'
            elif elem_type == 'quote':
                attr = f" — {meta}" if meta else ""
                html += f"<blockquote><p>{content}{attr}</p></blockquote>\n"
            elif elem_type == 'divider':
                html += "<hr>\n"
            elif elem_type == 'image':
                cap = meta.get('caption', '') if meta else ''
                html += f'<figure><img src="{content}" style="max-width:100%"><figcaption>{cap}</figcaption></figure>\n'
            elif elem_type == 'pagebreak':
                html += '<div style="page-break-after: always;"></div>\n'
